class Cart {
    private ArrayList<Integer> prices;
    private int pct;
    public Cart(int discountPct) {
        prices = new ArrayList<Integer>();
        pct = discountPct;
    }
    public void add(int price) {
        prices.add(price);
    }
    public int total() {
        int t = 0;
        for (int p : prices) {
            t += p;
        }
        return t - t * pct / 100;
    }
    // other methods not shown
}
```

